import time

from ta_ue_plugin_android.ue.android.android_ue import AndroidUe
from ta_ue_plugin_android.ue.at_cmds_ue.at_data_transfer_icmp import AtDataTransferIcmp
from ta_ue_plugin_android.uepc.ue_manager_exceptions import ReservationError
from ta_ue_plugin_android.ue.android.android_data_transfer import AndroidDataTransfer
from ta_ue_plugin_android.ue.common.specific_keywords_list import get_qualcomm_at_specific_keywords_list
from ta_ue_plugin_android.uepc.ue_manager_exceptions import CannotAttachError, CannotDetachError


class AtCmdsUe(AndroidUe):
    """
    Module to control AT command based UEs that connect with mbn (netsh) or ppp (radial) connection
    Supported platform: Windows
    """

    def __init__(self, name, serial_number, configuration, pyro_client, reservation_validator=lambda: True):
        """

        :param name:
        :param serial_number:
        :param configuration:
        :param pyro_client:
        :param reservation_validator:
        """
        super(AtCmdsUe, self).__init__(name, serial_number, configuration, pyro_client, reservation_validator)
        self.configuration = configuration

    def set_iperf(self, configuration):
        """Set iperf"""
        if 'iperf_interface_ip' in configuration['data_transfer']:
            return configuration['data_transfer']['iperf_interface_ip']
        return configuration['data_transfer']['ssh']['host']

    def prepare_ue(self):
        """Prepare Android UE"""
        try:
            self.logger.debug("prepare_ue before reserve")
            self._method_proxy('reserve_ue')
            self.logger.debug("prepare_ue after reserve")
            self._method_proxy('configure_ue', self.configuration)
            self.logger.debug("prepare_ue after configure_ue")
            self._method_proxy('connect_to_at_serial_port')
            self.logger.debug("prepare_ue after connect_to_at_serial_port")
        except Exception as e:
            self.logger.error("UE preparation exception: {}\n UE will be unreserved".format(e))
            self._method_proxy('unreserve_ue')
            raise ReservationError('Failure during UE preparation. UE {} was not reserved.'.format(self.name))

    def _get_specific_keywords_list(self):
        return get_qualcomm_at_specific_keywords_list()

    def attach(self, timeout=40):
        """
        Perform attach on UE.

        :param timeout: Time in seconds during which UE should change state to attached
        :return: None
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If attach failed
        """
        self.logger.info('attach')
        self._send_and_handle_command_with_timeout('attach', timeout, CannotAttachError)

    def detach(self, timeout=30):
        """
        Perform detach on UE.

        :param timeout: Time in seconds during which UE should change state to detached
        :return: None
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If attach failed
        """
        self.logger.info('detach')
        self._send_and_handle_command_with_timeout('detach', timeout, CannotDetachError)

    def _send_and_handle_command_with_timeout(self, method_name, timeout, exception_to_raise=Exception):
        self._method_proxy('reset_oneway_flags')
        self._oneway_method_proxy(method_name, timeout)
        is_finished, do_raise, err_msg = self._method_proxy('is_method_completed')
        while not is_finished:
            self.logger.info('Awaiting for finish of {}'.format(method_name))
            time.sleep(1)
            is_finished, do_raise, err_msg = self._method_proxy('is_method_completed')
        if do_raise:
            raise exception_to_raise(err_msg)
        self.logger.info('{} finished'.format(method_name))

    def _get_data_transfer_class(self, dt_definition):
        """
        Returns a data transfer class based on protocol
        :return: dict
        """
        if dt_definition.protocol in ['http', 'ftp']:
            raise NotImplementedError('Protocol {} not supported for given UE type'.format(dt_definition.protocol))
        protocol_to_class = {'icmp': AtDataTransferIcmp}
        return protocol_to_class.get(dt_definition.protocol, AndroidDataTransfer)
